182	    17	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
183	    18	        BigDecimal subtotal = Money.ZERO;
184	    19	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
185	    20	            subtotal = subtotal.add(nightPrice(room, night));
186	    21	        }
187	    22	        BigDecimal discount = plan.discountOn(subtotal);
188	    23	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
189	    24	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
190	    25	    }
