192	    27	    public static BigDecimal nightPrice(Room room, LocalDate night) {
193	    28	        BigDecimal rate = room.nightlyRate();
194	    29	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
195	    30	    }
196	    31	
197	    32	    /** De 15 de dezembro ao fim de fevereiro, e julho inteiro. */
198	    33	    static boolean isHighSeason(LocalDate night) {
199	    34	        Month month = night.getMonth();
200	    35	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
201	    36	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
202	    37	    }
