458	     4	    private EmailAddress() {
459	     5	    }
460	     6	
461	     7	    /** Um único @, algo antes dele e, depois, um nome com ao menos um ponto no meio. */
462	     8	    public static boolean isValid(String address) {
463	     9	        if (address == null) {
464	    10	            return false;
465	    11	        }
466	    12	        int at = address.indexOf('@');
467	    13	        if (at <= 0 || at != address.lastIndexOf('@')) {
468	    14	            return false;
469	    15	        }
470	    16	        String domain = address.substring(at + 1);
471	    17	        int dot = domain.indexOf('.');
472	    18	        while (dot >= 0) {
473	    19	            if (dot > 0 && dot < domain.length() - 1) {
474	    20	                return true;
475	    21	            }
476	    22	            dot = domain.indexOf('.', dot + 1);
477	    23	        }
478	    24	        return false;
479	    25	    }
480	    26	}
